import sys

class Solution:
    def isScramble(self, S1: str, S2: str) -> bool:
        n = len(S1)
        if n == 0:
            return True
        if n == 1:
            return S1 == S2

        memo = {}

        def dp(i: int, j: int, length: int) -> bool:
            if (i, j, length) in memo:
                return memo[(i, j, length)]

            s1_sub = S1[i:i+length]
            s2_sub = S2[j:j+length]

            if s1_sub == s2_sub:
                memo[(i, j, length)] = True
                return True

            if sorted(s1_sub) != sorted(s2_sub):
                memo[(i, j, length)] = False
                return False

            for k in range(1, length):
                if (dp(i, j, k) and dp(i + k, j + k, length - k)) or \
                   (dp(i, j + length - k, k) and dp(i + k, j, length - k)):
                    memo[(i, j, length)] = True
                    return True

            memo[(i, j, length)] = False
            return False

        return dp(0, 0, n)

def main():
    input_data = sys.stdin.read().split()
    if len(input_data) < 2:
        return
    S1 = input_data[0]
    S2 = input_data[1]

    sol = Solution()
    result = sol.isScramble(S1, S2)

    if result:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
